    for (int num : numbers) {  // Crashes if null!
        sum += num;
    }
    return (double) sum / numbers.length;  // Division by 0 if empty!
}

// ✅ Best Practice
double calculateAverage(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        System.err.println("Array is null or empty");
        return 0.0;
    }

    int sum = 0;
    for (int num : numbers) {
        sum += num;
    }
    return (double) sum / numbers.length;
