// Best practices example
public class BestPractices {
    private static final int MAX_STUDENTS = 30;
    private static final int PASSING_GRADE = 60;

    private int[] studentGrades = new int[MAX_STUDENTS];
    private int studentCount = 0;

    public boolean addGrade(int grade) {
        if (studentCount >= MAX_STUDENTS) {
            System.err.println("Class is full");
            return false;
        }

        if (grade < 0 || grade > 100) {
            System.err.println("Invalid grade: " + grade);
            return false;
        }

        studentGrades[studentCount++] = grade;
        return true;
    }

    public double calculateAverage() {
        if (studentCount == 0) {
            System.err.println("No grades to average");
            return 0.0;
        }

        int sum = 0;
        for (int i = 0; i < studentCount; i++) {
            sum += studentGrades[i];
        }

        return (double) sum / studentCount;
    }
}
